Rename the variable `userId` to `accountId` in ALL occurrences in this file:

```typescript
interface UserSession {
  userId: string;
  token: string;
  expiresAt: Date;
}

export function createSession(userId: string, token: string): UserSession {
  return {
    userId,
    token,
    expiresAt: new Date(Date.now() + 3600000),
  };
}

export function isValidSession(session: UserSession): boolean {
  if (!session.userId || !session.token) {
    return false;
  }
  return session.expiresAt > new Date();
}

export function getSessionKey(session: UserSession): string {
  return `session:${session.userId}:${session.token}`;
}
```
